  ['term'=>'وزن معیار','definition'=>'اهمیت نسبی معیار در قاعده رتبه‌بندی انتخاب‌شده.'],
  ['term'=>'وزن نرمال‌شده','definition'=>'وزنی که بر مجموع وزن‌ها تقسیم شده تا مجموع وزن‌ها یک باشد.'],
  ['term'=>'مقیاس‌سازی','definition'=>'تبدیل مقادیر به مقیاس قابل‌ترکیب یا مقایسه.'],
  ['term'=>'روش جبرانی','definition'=>'روش که در آن عملکرد بهتر یک معیار می‌تواند ضعف معیار دیگر را جبران کند.'],
  ['term'=>'AHP','definition'=>'روش تحلیل سلسله‌مراتبی مبتنی بر مقایسه‌های زوجی برای استخراج وزن‌ها.'],
  ['term'=>'مقایسه زوجی','definition'=>'قضاوت درباره اهمیت نسبی دو معیار در یک ماتریس.'],
  ['term'=>'ماتریس متقابل','definition'=>'ماتریسی که aⱼᵢ=1/aᵢⱼ و قطر اصلی آن یک است.'],
  ['term'=>'λmax','definition'=>'تقریب بزرگ‌ترین مقدار ویژه برای ارزیابی سازگاری ماتریس AHP.'],
  ['term'=>'شاخص سازگاری CI','definition'=>'شاخص انحراف سازگاری در AHP نسبت به ماتریس کاملاً سازگار.'],
  ['term'=>'نسبت سازگاری CR','definition'=>'نسبت CI به شاخص تصادفی RI در آزمون سازگاری AHP.'],
